// ============================================================================
// TYPES & DATA MODELS
// ============================================================================

type Category = 'Women' | 'Men' | 'Accessories';
type SizeOption = 'XS' | 'S' | 'M' | 'L' | 'XL' | 'One Size';
type ViewMode = 'home' | 'shop' | 'product' | 'lookbook' | 'checkout';
type SortOption = 'featured' | 'price-asc' | 'price-desc' | 'newest' | 'rating';

interface ColorVariant {
  name: string;
  hex: string;
  images: string[];
}

interface ReviewItem {
  id: string;
  author: string;
  city: string;
  rating: number;
  date: string;
  comment: string;
  verifiedSize?: string;
}

interface Product {
  id: string;
  brand: string;
  title: string;
  subtitle: string;
  category: Category;
  subcategory: string;
  price: number;
  originalPrice?: number;
  isNew?: boolean;
  isBestSeller?: boolean;
  isFeatured?: boolean;
  rating: number;
  reviewCount: number;
  sizes: SizeOption[];
  colors: ColorVariant[];
  description: string;
  fabricAndCare: string[];
  fitAndSizing: string[];
  shippingAndReturns: string;
  tags: string[];
  reviews: ReviewItem[];
}

interface CartItem {
  key: string;
  productId: string;
  brand: string;
  title: string;
  price: number;
  image: string;
  size: SizeOption;
  colorName: string;
  colorHex: string;
  quantity: number;
}

interface Hotspot {
  id: string;
  productId: string;
  xPercent: number;
  yPercent: number;
  label: string;
}

interface ToastMessage {
  id: number;
  text: string;
}

